VALUES ('fm-il-duplicate-meaning', NULL, 'IL-ONE-MEANING-1', 'failure-mode detector',
  'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM agent_issues a WHERE a.status = ''open'' AND (a.title LIKE ''METRIC-REGRESSION-1: %'' OR a.title LIKE ''METRIC-FIX-RELAPSED-1: %'') AND substr(a.title, instr(a.title, '': '') + 2) <> ''papers_live_failing_release_gate'' AND EXISTS (SELECT 1 FROM metric_registry r WHERE r.metric = substr(a.title, instr(a.title, '': '') + 2) AND instr(COALESCE(r.target, ''''), ''[superseded by'') = 0) AND NOT EXISTS (SELECT 1 FROM analytics_metric_triggers t WHERE t.metric_key = substr(a.title, instr(a.title, '': '') + 2) AND t.enabled = 1) AND EXISTS (SELECT 1 FROM analytics_metric_triggers t2 WHERE t2.metric_key = substr(a.title, instr(a.title, '': '') + 2) AND instr(COALESCE(t2.notes, ''''), ''BREACH-ONE-MEANING-1'') > 0)) AS TEXT) AS observed',
  'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', 45000, 5, 0, datetime('now'));

-- 4. A measuring contract for each open ticket of the six metrics, and the drill probe as the contract of 1000422.
UPDATE remediation_contracts SET verify_probe = 'SELECT ''carried'' AS expected, CASE WHEN instr(COALESCE((SELECT target FROM metric_registry WHERE metric = ''fleet_ai_run_rate_30d_usd''), ''''), ''[superseded by monthly_cost_run_rate_usd'') = 0 THEN ''fleet_ai_run_rate_30d_usd is not marked superseded by monthly_cost_run_rate_usd in metric_registry'' WHEN NOT EXISTS (SELECT 1 FROM analytics_metric_triggers WHERE metric_key = ''monthly_cost_run_rate_usd'' AND enabled = 1) THEN ''monthly_cost_run_rate_usd has no enabled trigger, so nothing carries the breach of fleet_ai_run_rate_30d_usd'' ELSE ''carried'' END AS observed', verify_transport = 'd1-query',
  action = 'MEASURES the closing condition: fleet_ai_run_rate_30d_usd is retired from IMPROVEMENT-LOOP-1 by the superseded marker and monthly_cost_run_rate_usd carries its breach with an enabled trigger (IL-ONE-MEANING-1, BREACH-ONE-MEANING-1). The loop closes the ticket with the same evidence.',
  status = 'active', last_verdict = NULL, attempts = 0, module = 'il-one-meaning-1', next_due_at = datetime('now')
WHERE class IN (SELECT 'issue-' || a.id FROM agent_issues a WHERE a.status = 'open' AND a.title IN ('METRIC-REGRESSION-1: fleet_ai_run_rate_30d_usd', 'METRIC-FIX-RELAPSED-1: fleet_ai_run_rate_30d_usd')) AND status = 'monitoring';

