  action = 'MEASURES the closing condition: issue_mttr_h_30d is retired from IMPROVEMENT-LOOP-1 by the superseded marker and mttr_h_7d carries its breach with an enabled trigger (IL-ONE-MEANING-1, BREACH-ONE-MEANING-1). The loop closes the ticket with the same evidence.',
  status = 'active', last_verdict = NULL, attempts = 0, module = 'il-one-meaning-1', next_due_at = datetime('now')
WHERE class IN (SELECT 'issue-' || a.id FROM agent_issues a WHERE a.status = 'open' AND a.title IN ('METRIC-REGRESSION-1: issue_mttr_h_30d', 'METRIC-FIX-RELAPSED-1: issue_mttr_h_30d')) AND status = 'monitoring';

UPDATE remediation_contracts SET verify_probe = (SELECT probe_sql FROM control_alternate_probes WHERE control = 'improvement-loop-superseded-marker'), verify_transport = 'd1-query',
  action = 'MEASURES the closing condition: the drill probe of control improvement-loop-superseded-marker reads ok (every superseded marker names a registered successor with an enabled trigger or a continued chain). IL-ONE-MEANING-1.',
  status = 'active', last_verdict = NULL, attempts = 0, module = 'il-one-meaning-1', next_due_at = datetime('now')
WHERE class = 'issue-1000422' AND status = 'monitoring' AND instr((SELECT probe_sql FROM control_alternate_probes WHERE control = 'improvement-loop-superseded-marker'), 'no metric carries a superseded marker') > 0;

-- 5. Two issues with a doer: the loop defects that need code in qnfo-fleet-control/worker.js (the file is claimed by the code loop; the code loop takes these next).
INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'IL-OWNER-OUTCOME-1: IMPROVEMENT-LOOP-1 files METRIC-REGRESSION-1 and METRIC-FIX-RELAPSED-1 tickets for owner-outcome metrics that were taken off the autonomic board on purpose',
  'Charter pillar: autonomy (owner directive 2026-10-26 one meaning per breach; ISSUE-SLA-2H-1: a finding that is not a defect is never an open issue). Read 2026-10-26 20:20Z: five open tickets stand on three owner-outcome metrics and one under-sampled one (100281 METRIC-FIX-RELAPSED-1 subscribers_growth_monthly, 100282 and 100304 outreach_reply_rate_30d, 100285 social_engagement_rate_30d, 100286 attention_decision_efficacy_30d). The triggers of the first three (341, 405, 404) are disabled on purpose (notes REDERIVE-2026-10-18: OWNER-OUTCOME, the fleet cannot manufacture subscribers, contacts or replies) and their registry disposition_actor reads OWNER (outcome metric; not autonomically closable), yet improvementEvaluate keeps filing and holding a regression ticket (7d mean against the prior 7d) and a relapse ticket (the 2026-10-19 closures) for each. No loop can close them: they stay open until strangers act, and count against open_agent_issues, the 120-minute SLA metrics and metric_regressions_7d. IL-ONE-MEANING-1 (migrations/2026-10-26-il-one-meaning.sql) put the marker [owner-outcome: not autonomically closable, IL-OWNER-OUTCOME-1] on the target of the three metrics; the loop does not read it yet.
Edit (one function, qnfo-fleet-control/worker.js improvementEvaluate): a registry target containing [owner-outcome makes the metric an early warning, never a defect: in the regression branch the var offTarget line becomes false for such a metric (the finding keeps file: false and the tick closes an open ticket with the existing early-warning evidence), and in the relapse loop a still-off-target relapse of such a metric is recorded with file: false and a close_evidence that names OWNER-OUTCOME (regTarget[metric] already holds the target text). The metric stays in trends, target_misses and fix_target_hold_rate_30d; nothing about its measurement or history changes. A metric with disabled triggers and no marker keeps its checks (the IL-SUPERSEDED-1 test pins that). Test: extend qnfo-fleet-control/improvement-superseded.test.mjs with an owner-outcome metric that regresses and relapses (files nothing, closes an open ticket with evidence naming OWNER-OUTCOME) and a control without the marker (still files).
Definition of done: the code-probe below; after the deploy the open tickets of the three metrics close at the next hourly tick.
code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js
code-anchor: var offTarget = rows.length && rows[rows.length - 1].meets === 0;
code-probe: {"paths": ["qnfo-fleet-control/worker.js"], "contains": "[owner-outcome"}',
  'session', 'autonomy', 'medium', 'open',
  CAST(strftime('%s', 'now') AS INTEGER) * 1000,
  CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title = 'IL-OWNER-OUTCOME-1: IMPROVEMENT-LOOP-1 files METRIC-REGRESSION-1 and METRIC-FIX-RELAPSED-1 tickets for owner-outcome metrics that were taken off the autonomic board on purpose');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'IL-TRIGGER-AWARE-1: IMPROVEMENT-LOOP-1 files a METRIC-REGRESSION-1 ticket for a metric whose enabled trigger is clear, so a drift inside the trigger band stays an open defect',
  'Charter pillar: autonomy (ISSUE-SLA-2H-1: a finding that is not a defect is never an open issue; IL-RELAPSE-TRIGGER-1 already judges a relapse by the closing trigger''s predicate for the same reason). Read 2026-10-26 20:20Z: four open regression tickets stand on metrics whose enabled trigger is clear: 100494 gateway_cap_30d_usd (trigger 364 gt 180, value 180), 100572 improvement_rate_7d (387 lt 0.3, value 0.335), 1000245 driver_drain_24h (4990 lt 0.05, value 0.231), 1000286 blocker_survival_rate_7d (3393 gt 0.25, value 0.015; a relative change on a base near zero: 0.0034 against 0.0027, and its registry target 0 makes any positive value off target). improvementEvaluate files a regression when the latest metric_history row has meets = 0 against the registry target, which is stricter than the trigger the fleet uses as its defect line.
Edit (one function, qnfo-fleet-control/worker.js improvementEvaluate, the regression branch): where var offTarget is computed, look up the enabled readable triggers of the metric (f.trigger_metric maps trigger id to metric key and f.trigger_pred holds each predicate; ilTriggerPred and ilTriggerHit already exist) and, when at least one exists, set offTarget to whether any of them is hit by the latest metric_history value; with no enabled trigger keep the registry-target test. The finding then keeps file: false for a drift inside the trigger band, with the existing early-warning evidence, and stays in trends and in GET /improvement. Test: in qnfo-fleet-control/improvement-superseded.test.mjs or a new improvement-trigger-aware.test.mjs a regressed metric with an enabled trigger that is clear files nothing and closes an open ticket with early-warning evidence; with the trigger hit it files; with no trigger it files as before.
Definition of done: the code-probe below; after the deploy the four tickets close at the next hourly tick.
code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js
code-anchor: var offTarget = rows.length && rows[rows.length - 1].meets === 0;
code-probe: {"paths": ["qnfo-fleet-control/worker.js"], "contains": "trigger band"}',
  'session', 'autonomy', 'medium', 'open',
  CAST(strftime('%s', 'now') AS INTEGER) * 1000,
  CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title = 'IL-TRIGGER-AWARE-1: IMPROVEMENT-LOOP-1 files a METRIC-REGRESSION-1 ticket for a metric whose enabled trigger is clear, so a drift inside the trigger band stays an open defect');

-- 6. The decision (decision_log is append-only: one row, guarded so a replay adds none).
INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
